	/* @Test */
	public void testWcharT()
    {

		DataType dt;
		Structure sdt;
		DataTypeComponent comp;

		CParser parser;
		parser = new CParser(); // uses default data organization (i.e., x86-32)
		dt = parser.parse("typedef short wchar_t;");
		assertTrue(dt is WideCharDataType);

		parser = new CParser();
		dt = parser.parse("struct mystruct {" +
			"    wchar_t defined_wchar_t;" +
			"};");

		sdt = (Structure) dt;
		comp = sdt.getComponent(0);
		assertTrue(comp.getDataType() is WideCharDataType);

		parser = new CParser();
		dt = parser.parse("typedef int wchar_t;" +
			"struct mystruct {" +
			"    wchar_t defined_wchar_t;" +
			"};");

		sdt = (Structure) dt;
		comp = sdt.getComponent(0);
		assertTrue(comp.getDataType() is WideCharDataType);

		parser = new CParser();
		dt = parser.parse("typedef short wchar_t;" +
			"  typedef wchar_t foo;");

		assertTrue(dt != null);
		assertTrue(dt is TypeDef);
		assertTrue(dt.getName().equals("foo"));
		assertEquals(2, dt.getLength());
		assertTrue(((TypeDef) dt).getBaseDataType() is BuiltInDataType);

		parser = new CParser();
		DataType pdt32 = parser.parse("typedef wchar_t foo;");
		assertTrue(dt != null);
		assertTrue(dt is TypeDef);
		assertTrue(dt.getName().equals("foo"));
		assertEquals(2, dt.getLength());
		assertTrue(((TypeDef) dt).getBaseDataType() is BuiltInDataType);
	}

